    <*> fieldStr "path" kv
    <*> fieldBool "head" kv
    <*> fieldOpt "status" kv
    <*> fieldOpt "since" kv
    <*> fieldStr "rc" kv

encodeMainRecord :: MainRecord -> Fields
encodeMainRecord r =
  [ ("main", encBool (mainRecordMain r))
  , ("path", encStr (mainRecordPath r))
  , ("head", encBool (mainRecordHead r))
  , ("status", encOpt (mainRecordStatus r))
  , ("since", encOpt (mainRecordSince r))
  , ("rc", encStr (mainRecordRc r))
  ]

mainRecordMainL :: Lens' MainRecord (Bool)
mainRecordMainL k r = (\v -> r { mainRecordMain = v }) <$> k (mainRecordMain r)
{-# INLINE mainRecordMainL #-}

mainRecordPathL :: Lens' MainRecord (String)
mainRecordPathL k r = (\v -> r { mainRecordPath = v }) <$> k (mainRecordPath r)
{-# INLINE mainRecordPathL #-}

mainRecordHeadL :: Lens' MainRecord (Bool)
mainRecordHeadL k r = (\v -> r { mainRecordHead = v }) <$> k (mainRecordHead r)
{-# INLINE mainRecordHeadL #-}

mainRecordStatusL :: Lens' MainRecord (Maybe String)
mainRecordStatusL k r = (\v -> r { mainRecordStatus = v }) <$> k (mainRecordStatus r)
{-# INLINE mainRecordStatusL #-}

mainRecordSinceL :: Lens' MainRecord (Maybe String)
mainRecordSinceL k r = (\v -> r { mainRecordSince = v }) <$> k (mainRecordSince r)
{-# INLINE mainRecordSinceL #-}

mainRecordRcL :: Lens' MainRecord (String)
